using System;
using PocketWilds.Core;
using UnityEngine;

namespace PocketWilds.Presentation
{
    /// <summary>
    /// Weather of a biome (DEF_Weather_&lt;Biome&gt;, doc 04: Grassland light rain and rainbow) plus the sun rays of the
    /// Magnifique tier. Meshes and materials are generated by the environment pipeline; WeatherSystem draws them.
    /// </summary>
    [CreateAssetMenu(menuName = "Pocket Wilds/World/Weather Kit", fileName = "DEF_Weather_Biome")]
    public sealed class WeatherKit : ScriptableObject
    {
        [Header("Rain")]
        public Mesh rainMesh;
        public Material rainMaterial;
        [Tooltip("Streaks on Magnifique; tiers scale it (WorldQualityProfile.weather).")]
        [Min(0)] public int maxDrops = 700;
        [Tooltip("Rain box around the camera focus: x and z extent, height (m).")]
        public Vector3 rainBox = new Vector3(18f, 10f, 18f);

        [Header("Rainbow")]
        public Mesh rainbowMesh;
        public Material rainbowMaterial;
        [Min(1f)] public float rainbowDistance = 55f;
        [Min(1f)] public float rainbowRadius = 30f;

        [Header("Sun rays (Magnifique)")]
        public Mesh rayMesh;
        public Material rayMaterial;
        [Tooltip("T50: lowest tier with the rays. High follows DEF_WorldQuality (Magnifique); the Forest's shafts start at Medium (Équilibrée).")]
        public QualityTier sunRaysFrom = QualityTier.High;
        [Tooltip("T50: world x ranges (min, max) where the rays stand, faded over 2 m past each end (the Forest: Entry and Clearing). Empty: everywhere.")]
        public Vector2[] sunRayAreas = Array.Empty<Vector2>();
        [Tooltip("T50: how far past the camera focus the rays stand (m, away from the camera). The Forest's stand behind the landmarks' trunks so they stay solid.")]
        [Min(0f)] public float rayDepth = 3.5f;

        [Header("Schedule (minutes of play, seconds)")]
        [Tooltip("Minutes between two showers: a random value in this range.")]
        public Vector2 showerEveryMinutes = new Vector2(18f, 35f);
        [Tooltip("Seconds of full rain: a random value in this range.")]
        public Vector2 showerSeconds = new Vector2(70f, 110f);
        [Min(1f)] public float rampSeconds = 12f;
        [Min(1f)] public float rainbowSeconds = 50f;
    }
}
